const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'entityId', 'workspaceId', 'userId', 'input', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

const brief = body.input;
if (!brief || !brief.what || !brief.what.scenario || !brief.what.channel) {
  throw new Error('brief.what.scenario et brief.what.channel sont requis');
}

// ADR-0013 Lot 3 — outputKind (brief.what.outputKind) est la source de vérité.
// Fallback channel-based pour les runs antérieurs au Lot 2, stockés sans ce
// champ (non-régression ADR-0013 §6.2) — jamais l'inverse.
const PITCH_CHANNELS = ['spoken_pitch_30s', 'meeting_briefing'];
const CANONICAL_OUTPUT_KINDS = ['written_message', 'spoken_pitch', 'structured_briefing'];
let outputKind = brief.what.outputKind
  || (PITCH_CHANNELS.includes(brief.what.channel)
    ? (brief.what.channel === 'spoken_pitch_30s' ? 'spoken_pitch' : 'structured_briefing')
    : 'written_message');
if (!CANONICAL_OUTPUT_KINDS.includes(outputKind)) {
  throw new Error(`brief.what.outputKind invalide : "${outputKind}" (attendu : ${CANONICAL_OUTPUT_KINDS.join(', ')})`);
}
const isPitch = outputKind !== 'written_message';

// Lot 10 — normalisation canonique (command §1). "interne_management" ne doit
// plus jamais être PRODUIT par un brief neuf, mais reste ACCEPTÉ en lecture
// pour les runs antérieurs au Lot 2 (communication-legacy-normalizer.ts, front)
// — même règle des deux côtés, scope explicite obligatoire pour désambiguïser.
const CANONICAL_CATEGORIES = ['commerce_prospection', 'commerce_actif', 'delivery', 'recrutement', 'management_consultants', 'internal_staff'];
const CATEGORY_SCOPE = {
  commerce_prospection: 'account',
  commerce_actif: 'account',
  delivery: 'account',
  recrutement: 'account',
  management_consultants: 'collaborator',
  internal_staff: 'internal',
};
const CANONICAL_SCOPES = ['account', 'collaborator', 'internal'];

let scope = brief.what.scope || null;
let activityCategory = brief.what.activityCategory || null;

if (activityCategory === 'interne_management') {
  if (scope === 'collaborator') {
    activityCategory = 'management_consultants';
  } else if (scope === 'internal') {
    activityCategory = 'internal_staff';
  } else {
    throw new Error('Impossible de normaliser la catégorie legacy "interne_management" sans scope explicite ("collaborator" ou "internal")');
  }
}

if (brief.what.scenario === 'profile_submission') {
  brief.what.scenario = 'profile_submission_to_client';
}

if (activityCategory && !CANONICAL_CATEGORIES.includes(activityCategory)) {
  throw new Error(`brief.what.activityCategory invalide : "${activityCategory}" (attendu : ${CANONICAL_CATEGORIES.join(', ')})`);
}

// Fallback scope pour les runs antérieurs au Lot 0 ADR-0013 (aucun scope stocké) :
// déduit de la catégorie si elle est connue, sinon "account" (comportement
// historique — tous les runs pré-scope étaient des scénarios commerciaux/compte).
if (!scope) {
  scope = (activityCategory && CATEGORY_SCOPE[activityCategory]) || 'account';
}
if (!CANONICAL_SCOPES.includes(scope)) {
  throw new Error(`brief.what.scope invalide : "${scope}" (attendu : ${CANONICAL_SCOPES.join(', ')})`);
}

// Cohérence scénario/scope (command §1) — une catégorie account ne peut pas
// arriver avec scope collaborator/internal et réciproquement. Défensif : le
// résolveur front garantit déjà cette cohérence, mais n8n ne doit pas faire
// confiance aveuglément à un payload externe.
if (activityCategory) {
  const expectedScope = CATEGORY_SCOPE[activityCategory];
  if (expectedScope && expectedScope !== scope) {
    throw new Error(`Incohérence scope/catégorie : "${activityCategory}" exige scope "${expectedScope}", reçu "${scope}"`);
  }
}

// ADR-0013 D-5 (supersede ADR-0009 §6) — l'offre catalogue n'est obligatoire
// que pour les scénarios qui s'y ancrent explicitement. Liste synchronisée
// avec requiresOffer=true dans communication-scenario-registry.ts (front,
// OFFER_REQUIRED_SCENARIOS) — Lot 10 corrige une dérive : 3 scénarios avaient
// été oubliés (offer_introduction, cross_sell, proposal_defense_pitch) depuis
// le Lot 2 du registre front (à maintenir en parallèle des deux côtés).
const SCENARIOS_REQUIRING_OFFER = new Set([
  'offer_introduction',
  'cross_sell',
  'cold_call_pitch',
  'meeting_prep_cross_sell',
  'proposal_defense_pitch',
  'renewal_pitch',
]);
const offerRef = (brief.context && brief.context.offerRef) || null;
const requiresOffer = SCENARIOS_REQUIRING_OFFER.has(brief.what.scenario);

if (requiresOffer && !offerRef) {
  throw new Error(`brief.context.offerRef est requis pour le scénario "${brief.what.scenario}" (ADR-0013 D-5)`);
}

// Lot 10 — champs obligatoires par scope (command §1 "vérifier les champs
// obligatoires selon le scope"). Aucune référence CRM requise pour
// collaborator/internal (command §4) : uniquement l'identité du destinataire
// réel de ce scope.
const recipient = (brief.who && brief.who.recipient) || {};
const collaboratorRef = (brief.context && brief.context.collaboratorRef)
  || recipient.collaboratorId
  || (body.entityType === 'collaborator' ? body.entityId : null)
  || null;

if (scope === 'collaborator' && !collaboratorRef) {
  throw new Error('brief.context.collaboratorRef (ou who.recipient.collaboratorId) est requis pour scope="collaborator"');
}

const internalRole = recipient.internalRole || null;
const internalRelationship = recipient.internalRelationship || null;
const internalDomain = recipient.internalDomain || null;

if (scope === 'internal' && !internalRole) {
  throw new Error('brief.who.recipient.internalRole est requis pour scope="internal"');
}

// Lot 10 — companyId prioritairement dérivé de body.entityType/entityId
// (compat historique, scope account), en repli brief.context.companyRef
// (Lot 9 — référence facultative pour delivery/internal_staff qui portent sur
// un client précis sans changer scope). Jamais les deux à la fois en pratique
// (companyRef n'a de sens que quand entityType !== 'company').
const companyId = body.entityType === 'company'
  ? body.entityId
  : ((brief.context && brief.context.companyRef) || null);

// Lot 10 — command §3 : structure explicite transmise par le Front, jamais
// déduite d'un texte mustExclude fabriqué (retiré côté front au Lot 7).
const ALL_CONTEXT_SOURCE_IDS = [
  'account_profile', 'crm_contacts', 'signal_intelligence', 'opportunity_context',
  'interaction_history', 'mission_context', 'candidate_profile', 'collaborator_context',
  'offer_catalog', 'source_document', 'previous_generation',
];
const disabledSources = new Set((brief.context && brief.context.disabledContextSources) || []);
const activeSources = ALL_CONTEXT_SOURCE_IDS.filter((id) => !disabledSources.has(id));

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    companyId: companyId,
    collaboratorId: collaboratorRef,
    brief: brief,
    callbackUrl: body.callbackUrl,
    scenario: brief.what.scenario,
    channel: brief.what.channel,
    outputKind: outputKind,
    activityCategory: activityCategory,
    scope: scope,
    isPitch: isPitch,
    requiresOffer: requiresOffer,
    contactId: recipient.contactId || null,
    opportunityRef: (brief.context && brief.context.opportunityRef) || null,
    missionRef: (brief.context && brief.context.missionRef) || null,
    profileRef: (brief.context && brief.context.profileRef) || null,
    offerRef: offerRef,
    internalRole: internalRole,
    internalRelationship: internalRelationship,
    internalDomain: internalDomain,
    internalDisplayName: recipient.displayName || null,
    activeSources: activeSources,
  }
}];

const upstream = $('Validate Brief').item.json;
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_SERVICE_ROLE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;

// Lot 10 — command §2 : routage par scope, plus par isPitch. Remplace la
// logique "isPitch ? get_pitch_context : get_communication_context" qui
// appelait un RPC compte pour un scope collaborator/internal (company_id
// toujours null) sans jamais hydrater le vrai contexte de ces scopes.
//
// "Hydrate Context" devient un nœud Code (plutôt que HTTP Request comme le
// reste du workflow, cf. SETUP.md §3) : le routage par scope, la fusion
// compte+offre et l'absence d'appel pour le scope internal ne sont pas
// exprimables dans une seule expression d'URL/body d'un nœud HTTP Request.
//
// Bug live corrigé (post-Lot 10) : `this.helpers.httpRequestWithAuthentication`
// n'est pas supporté dans le sandbox du nœud Code sur les versions n8n
// antérieures à 1.42.0 (erreur runtime confirmée sur le VPS : "The function
// 'helpers.httpRequestWithAuthentication' is not supported in the Code
// Node") — le credential store natif n8n ("supabaseApi") n'est donc PAS
// accessible depuis ce nœud, contrairement à l'hypothèse initiale du Lot 10.
// Remplacé par `this.helpers.httpRequest` (helper HTTP nu, supporté dans le
// nœud Code sur toutes les versions n8n) avec authentification construite à
// la main via `SUPABASE_SERVICE_ROLE_KEY` — variable déjà documentée au §1
// du SETUP.md mais jamais effectivement câblée jusqu'ici.
if (!SUPABASE_SERVICE_ROLE_KEY) {
  throw new Error('SUPABASE_SERVICE_ROLE_KEY manquante côté n8n (variable d\'environnement du conteneur, voir SETUP.md §1) — impossible d\'authentifier les appels RPC Supabase depuis ce nœud Code.');
}

const callRpc = async (fnName, params) => {
  return await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/rpc/${fnName}`,
    headers: {
      'Content-Profile': 'public',
      apikey: SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
    },
    body: params,
    json: true,
  });
};

// Lot 10 — command §3 : filtrage réel des sources. Mappe chaque identifiant
// de source (contrat wire CommunicationContextSourceId, front) vers les clés
// du contexte hydraté qu'il gouverne. Une source désactivée = ses clés ne
// sont jamais injectées dans `ctx` → jamais dans le prompt (Assemble Prompt
// ne fait que lire `if (ctx.X)`, aucun changement nécessaire côté rendu pour
// que le filtrage prenne effet).
const SOURCE_FIELD_MAP = {
  account_profile: ['company'],
  crm_contacts: ['contact'],
  signal_intelligence: ['sectorNews', 'sectorIntelligence'],
  opportunity_context: ['activeOpportunities', 'anchorOpportunity'],
  interaction_history: ['recentInteractions'],
  mission_context: ['activeMissions', 'anchorMission', 'currentMission', 'recentMissions'],
  candidate_profile: [],
  collaborator_context: ['collaborator', 'person', 'managerProfile', 'jobProfile', 'skills', 'availability', 'recentActivity', 'recentAbsences'],
  offer_catalog: ['offer', 'pricingGrid', 'suggestedPractices', 'deliveredPractices'],
  source_document: [],
  previous_generation: ['previousPitches', 'previousCommunications', 'legacyPitches'],
};

function applySourceFiltering(ctx, activeSources) {
  const active = new Set(activeSources || []);
  const filtered = { ...ctx };
  for (const [sourceId, fields] of Object.entries(SOURCE_FIELD_MAP)) {
    if (active.has(sourceId)) continue;
    for (const field of fields) delete filtered[field];
  }
  return filtered;
}

async function hydrateAccount() {
  const params = {
    p_workspace_id: upstream.workspaceId,
    p_company_id: upstream.companyId,
    p_contact_id: upstream.contactId,
    p_opportunity_id: upstream.opportunityRef,
    p_mission_id: upstream.missionRef,
  };
  const general = upstream.companyId ? await callRpc('get_communication_context', params) : {};

  const needsOffer = upstream.requiresOffer || Boolean(upstream.offerRef);
  if (!needsOffer || !upstream.companyId) return general || {};

  const pitch = await callRpc('get_pitch_context', {
    p_workspace_id: upstream.workspaceId,
    p_company_id: upstream.companyId,
    p_offer_id: upstream.offerRef,
    p_opportunity_id: upstream.opportunityRef,
    p_mission_id: upstream.missionRef,
  });

  // Fusion sans écraser (command §2) : le contexte général reste la base ;
  // seuls les champs propres à l'offre (absents du contexte général) sont
  // ajoutés par-dessus.
  const OFFER_ONLY_FIELDS = ['offer', 'pricingGrid', 'suggestedPractices', 'deliveredPractices', 'previousPitches', 'legacyPitches', 'scores'];
  const merged = { ...(general || {}) };
  for (const field of OFFER_ONLY_FIELDS) {
    if (pitch && pitch[field] !== undefined) merged[field] = pitch[field];
  }
  // anchorOpportunity/anchorMission (spécifiques à get_pitch_context) complètent
  // activeOpportunities/activeMissions sans les remplacer.
  if (pitch && pitch.anchorOpportunity) merged.anchorOpportunity = pitch.anchorOpportunity;
  if (pitch && pitch.anchorMission) merged.anchorMission = pitch.anchorMission;
  return merged;
}

async function hydrateCollaborator() {
  if (!upstream.collaboratorId) return {};
  const result = await callRpc('get_collaborator_communication_context', {
    p_workspace_id: upstream.workspaceId,
    p_collaborator_id: upstream.collaboratorId,
    ...(upstream.missionRef ? { p_mission_id: upstream.missionRef } : {}),
  });
  return result || {};
}

async function hydrateInternal() {
  // Lot 10 — command §2 : aucun RPC dédié au scope internal. Le contexte de
  // base vient exclusivement du brief (rôle/relation/domaine/nom), jamais
  // d'une donnée fabriquée. Les références facultatives (command §4) restent
  // enrichissables via les MÊMES RPC déjà utilisées pour account/collaborator
  // (pas une RPC nouvelle) — uniquement quand la référence est réellement présente.
  const ctx = {
    internalRecipient: {
      role: upstream.internalRole,
      relationship: upstream.internalRelationship,
      domain: upstream.internalDomain,
      displayName: upstream.internalDisplayName,
    },
  };

  if (upstream.companyId) {
    const general = await callRpc('get_communication_context', {
      p_workspace_id: upstream.workspaceId,
      p_company_id: upstream.companyId,
      p_opportunity_id: upstream.opportunityRef,
      p_mission_id: upstream.missionRef,
    });
    Object.assign(ctx, general || {});
  } else if (upstream.collaboratorId) {
    const collaboratorCtx = await hydrateCollaborator();
    Object.assign(ctx, collaboratorCtx);
  }

  return ctx;
}

let ctx;
if (upstream.scope === 'collaborator') {
  ctx = await hydrateCollaborator();
} else if (upstream.scope === 'internal') {
  ctx = await hydrateInternal();
} else {
  ctx = await hydrateAccount();
}

ctx = applySourceFiltering(ctx || {}, upstream.activeSources);

// Lot 10 — command §5 : contrat normalisé commun, transmis en plus des champs
// legacy déjà lus par Assemble Prompt/Parse & Validate Output/Quality
// Check/Prepare Callback (command §6 — compatibilité conservée, aucun de ces
// nœuds n'a besoin de ce contrat pour continuer à fonctionner).
const brief = upstream.brief;
const normalizedContract = {
  outputKind: upstream.outputKind,
  activityCategory: upstream.activityCategory,
  scope: upstream.scope,
  scenario: upstream.scenario,
  objective: (brief.who && brief.who.objective) || null,
  channel: upstream.channel,
  length: (brief.what && brief.what.length) || null,
  tone: (brief.how && brief.how.tone) || null,
  recipient: (brief.who && brief.who.recipient) || {},
  references: {
    companyId: upstream.companyId,
    contactId: upstream.contactId,
    opportunityRef: upstream.opportunityRef,
    missionRef: upstream.missionRef,
    profileRef: upstream.profileRef,
    collaboratorId: upstream.collaboratorId,
    offerRef: upstream.offerRef,
  },
  context: ctx,
  activeSources: upstream.activeSources,
  instructions: (brief.context && brief.context.mustInclude) || '',
};

// Lot 10 — command §6 "conserver la compatibilité avec les nœuds de génération
// existants" : Assemble Prompt lit `ctx = $('Hydrate Context').item.json` et
// accède directement à `ctx.company`, `ctx.activeOpportunities`, etc. — les
// champs hydratés doivent donc rester au niveau racine de cette sortie
// (comme l'était la réponse brute du RPC avec l'ancien nœud HTTP Request),
// `normalizedContract` s'ajoute en plus sans rien remplacer.
return [{
  json: {
    ...ctx,
    normalizedContract: normalizedContract,
  }
}];

// INTEL-020 Lot 11 — Assemblage de prompt en 4 couches.
//   Couche 1 : règles globales (identité sourcée, no-invention, préséance).
//   Couche 2 : forme + contrat de sortie par outputKind.
//   Couche 3 : garde-fous par activityCategory + scope (y compris chemin écrit).
//   Couche 4 : mission par scénario (flagship bespoke + template dérivé du manifeste).
// Le manifeste (SCENARIO_MANIFEST) est généré depuis la registry TS et inliné au
// build-time par scripts/generate-communication-manifest.mjs (C1).

const briefData = $('Validate Brief').item.json;
const ctx = $('Hydrate Context').item.json || {};
const senderRows = $('Resolve Sender').item.json;
const senderProfile = (Array.isArray(senderRows) ? senderRows[0] : senderRows) || {};
const { brief, scenario, outputKind, activityCategory } = briefData;

// MANIFEST:START
const SCENARIO_MANIFEST = [{"id":"annual_review_follow_up","category":"management_consultants","label":"Suivi d'entretien annuel","description":"Récapitule les décisions après un entretien annuel.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"confirm_next_steps","requiresOffer":false},{"id":"appointment_confirmation","category":"commerce_prospection","label":"Confirmation de rendez-vous","description":"Confirme un rendez-vous à venir avec les informations pratiques.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"confirm_next_steps","requiresOffer":false},{"id":"assignment_change_notice","category":"management_consultants","label":"Annonce changement de mission","description":"Informe un collaborateur d'un changement de mission ou de planning.","allowedOutputKinds":["written_message","spoken_pitch"],"defaultOutputKind":"written_message","defaultObjective":"announce_change","requiresOffer":false},{"id":"atypical_candidate_defense","category":"recrutement","label":"Défense d'un candidat atypique","description":"Brief pour argumenter en faveur d'un candidat au profil atypique.","allowedOutputKinds":["structured_briefing"],"defaultOutputKind":"structured_briefing","defaultObjective":"advocate_for_candidate","requiresOffer":false},{"id":"candidate_availability_check","category":"recrutement","label":"Demande de disponibilité / préavis","description":"Interroge un candidat sur sa disponibilité ou son préavis.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"request_action","requiresOffer":false},{"id":"candidate_closing_pitch","category":"recrutement","label":"Pitch closing candidat","description":"Script oral pour conclure un processus de recrutement avec un candidat.","allowedOutputKinds":["spoken_pitch"],"defaultOutputKind":"spoken_pitch","defaultObjective":"close_candidate","requiresOffer":false},{"id":"candidate_cv_completion_request","category":"recrutement","label":"Demande de complément CV","description":"Demande à un candidat de compléter son CV ou son portfolio.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"request_action","requiresOffer":false},{"id":"candidate_follow_up","category":"recrutement","label":"Relance candidat","description":"Relance un candidat resté sans réponse.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"get_reply","requiresOffer":false},{"id":"candidate_interview_invitation","category":"recrutement","label":"Invitation à un entretien candidat","description":"Invite un candidat à un entretien.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"invite_to_interview","requiresOffer":false},{"id":"candidate_offer","category":"recrutement","label":"Proposition d'embauche","description":"Transmet une proposition d'embauche formelle à un candidat.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"send_offer","requiresOffer":false},{"id":"candidate_post_interview_feedback","category":"recrutement","label":"Feedback après entretien","description":"Transmet un retour au candidat après un entretien.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"get_feedback","requiresOffer":false},{"id":"candidate_rejection","category":"recrutement","label":"Refus candidat","description":"Notifie un refus de candidature avec tact.","allowedOutputKinds":["written_message"],"defaultOutputKind":"written_message","defaultObjective":"reject_candidate","requiresOffer":false},{"id":"candidate_to_client_pitch","category":"recrutement","label":"Pitch candidat vers client","description":"Présente un candidat à un client de façon structurée et argumentée à l'oral.","allowedOutputKinds":["structured_briefing"],"defaultOutputKind":"st